export type AdminStatsConnectionSweepRecentFailuresItem = {
  tenantId: number;
  /**
     * Workspace name, null if the tenant was deleted.
     * @nullable
     */
  tenantName?: string | null;
  platform: string;
  error: string;
  at: string;
  /** How many sweeps in a row this tenant+platform check has failed, including this one. Values above 1 mark a chronic breakage rather than a one-off blip; the tally resets the first sweep the check succeeds. */
  consecutiveFailures?: number;
  /** When the current failure streak began, so admins can see how long the check has been failing without doing sweep-interval math. For rows recorded before this field existed the server falls back to the failure's own timestamp. */
  firstFailedAt?: string;
};

/**
 * Health of the background dead-connection sweep. Null when the sweep has never completed a run (e.g. fresh deploy).
 * @nullable
 */
export type AdminStatsConnectionSweep = {
  lastRunAt: string;
  durationMs: number;
  accountsChecked: number;
  errorCount: number;
  /** Fraction (0-1) of failed checks per run at or above which the sweep fires a mass-outage superadmin alert. Exposed so the dashboard can flag the last run's failure ratio using the same server-side threshold instead of hardcoding one. */
  failRatioAlertThreshold?: number;
  /** @nullable */
  lastError?: string | null;
  /** How many failing checks were trimmed from the persisted cross-run failure history when it exceeded its cap during the last run. Non-zero means the dashboard is NOT showing the full failure picture (e.g. a platform-wide outage broke more connections than the history keeps). */
  droppedStreaks?: number;
  /** Most recent failed checks from the last completed sweep run, newest first (capped server-side), so an admin can see which tenant + platform keeps timing out without reading logs. */
  recentFailures?: AdminStatsConnectionSweepRecentFailuresItem[];
} | null;

